import { jest } from '@jest/globals';
import type { LinearClient } from '@linear/sdk';
import type { LinearGraphQLClient } from '../../graphql/client';
import { config } from 'dotenv';

// Load environment variables from .env file
config();

/**
 * Approaches to fix TypeScript errors with Jest mocks:
 * 
 * 1. Type Assertion for Mock Function [Failed]
 * - Define specific function signature type
 * - Use type assertion to match Jest's Mock type
 * - Error: Generic type 'Mock' requires between 0 and 1 type arguments
 * 
 * 2. Custom Mock Type [Failed]
 * - Create interface extending LinearClient
 * - Use jest.MockInstance for specific method types
 * - Error: Namespace 'jest' has no exported member 'MockInstance'
 * 
 * 3. Jest's Mocked Utility Type [Trying this approach]
 * - Use jest.Mocked to type the entire client
 * - Pick only needed properties
 * 
 * 4. Simplified Mock Structure [Not tried yet]
 * - Minimal typing in setup
 * - Handle specific types in test files
 */

// Approach 3: Jest's Mocked Utility Type
type MockedGraphQLClient = {
  rawRequest: jest.Mock;
};

type MockedLinearClient = {
  client: MockedGraphQLClient;
};

// Create mock client factory function
const createMockClient = () => ({
  client: {
    rawRequest: jest.fn().mockImplementation(async () => ({ data: {} }))
  },
  viewer: Promise.resolve({ id: 'test-user', name: 'Test User' })
});

// Create mock constructor that creates new instances
const MockLinearClient = jest.fn(function(this: any) {
  return Object.assign(this, createMockClient());
});

// Mock the Linear SDK
jest.mock('@linear/sdk', () => ({
  LinearClient: MockLinearClient
}));

// Export mock for use in tests
export const getMockLinearClient = () => new (MockLinearClient as any)();

import { describe, it, expect, beforeAll } from '@jest/globals';
import { LinearAuth } from '../auth';
import { LinearClient } from '@linear/sdk';

// Skip tests if no credentials are configured
const hasAPIKeyCredentials = process.env.LINEAR_API_KEY;
const hasOAuthCredentials = process.env.LINEAR_CLIENT_ID && 
                          process.env.LINEAR_CLIENT_SECRET && 
                          process.env.LINEAR_REDIRECT_URI;

// Only run integration tests when credentials are available
(hasAPIKeyCredentials || hasOAuthCredentials ? describe : describe.skip)('LinearAuth Integration', () => {

  // API Key Authentication Tests
  (hasAPIKeyCredentials ? describe : describe.skip)('Personal Access Token Authentication', () => {
    let auth: LinearAuth;

    beforeAll(() => {
      auth = new LinearAuth();
      auth.initialize({
        type: 'api',
        apiKey: [REDACTED]
      });
    });

    it('should authenticate with API Key', () => {
      expect(auth.isAuthenticated()).toBe(true);
      expect(auth.needsTokenRefresh()).toBe(false);
    });

    it('should make authenticated requests with API Key', async () => {
      const client = auth.getClient();
      expect(client).toBeInstanceOf(LinearClient);

      // Try to fetch viewer info to verify token works
      const viewer = await client.viewer;
      expect(viewer).toBeDefined();
      expect(viewer.id).toBeDefined();
    });
  });

  // OAuth Authentication Tests
  (hasOAuthCredentials ? describe : describe.skip)('OAuth Flow', () => {
    let auth: LinearAuth;

    beforeAll(() => {
      auth = new LinearAuth();
      auth.initialize({
        type: 'oauth',
        clientId: process.env.LINEAR_CLIENT_ID!,
        clientSecret: [REDACTED],
        redirectUri: process.env.LINEAR_REDIRECT_URI!
      });
    });

    it('should generate valid authorization URL', () => {
      const url = auth.getAuthorizationUrl();
      expect(url).toContain('https://linear.app/oauth/authorize');
      expect(url).toContain(`client_id=${process.env.LINEAR_CLIENT_ID}`);
      expect(url).toContain(`redirect_uri=${encodeURIComponent(process.env.LINEAR_REDIRECT_URI!)}`);
      expect(url).toContain('response_type=code');
      expect(url).toContain('scope=read%2Cwrite%2Cissues%3Acreate%2Coffline_access');
      expect(url).toContain('actor=application');
      expect(url).toContain('state=');
    });

    // Skip token tests if we don't have auth code and refresh token
    const hasTokens = process.env.LINEAR_AUTH_CODE && process.env.LINEAR_REFRESH_TOKEN;
    (hasTokens ? it : it.skip)('should exchange auth code for tokens', async () => {
      const authCode = process.env.LINEAR_AUTH_CODE;
      if (!authCode) {
        throw new Error('LINEAR_AUTH_CODE environment variable is required');
      }

      await auth.handleCallback(authCode);
      expect(auth.isAuthenticated()).toBe(true);
    });

    (hasTokens ? it : it.skip)('should make authenticated requests with OAuth token', async () => {
      // Set initial token data (requires valid refresh token)
      const refreshToken = [REDACTED];
      if (!refreshToken) {
        throw new Error('LINEAR_REFRESH_TOKEN environment variable is required');
      }

      auth.setTokenData({
        apiKey: '[REDACTED]',
        refreshToken,
        expiresAt: Date.now() - 1000 // Expired
      });

      await auth.refreshAPIKey();
      expect(auth.isAuthenticated()).toBe(true);

      const client = auth.getClient();
      expect(client).toBeInstanceOf(LinearClient);

      // Try to fetch viewer info to verify token works
      const viewer = await client.viewer;
      expect(viewer).toBeDefined();
      expect(viewer.id).toBeDefined();
    });
  });
});

import { jest, describe, it, expect, beforeEach } from '@jest/globals';
import { LinearAuth } from '../auth';
import { McpError, ErrorCode } from '@modelcontextprotocol/sdk/types.js';

// Mock fetch
const mockFetch = jest.fn() as jest.MockedFunction<typeof fetch>;
global.fetch = mockFetch;

beforeEach(() => {
  mockFetch.mockClear();
});

describe('LinearAuth', () => {
  let auth: LinearAuth;

  beforeEach(() => {
    auth = new LinearAuth();
  });

  describe('initialize', () => {
    it('should initialize with valid OAuth credentials', () => {
      expect(() => {
        auth.initialize({
          type: 'oauth',
          clientId: 'test-client-id',
          clientSecret: '[REDACTED]',
          redirectUri: 'http://localhost:3000/callback'
        });
      }).not.toThrow();
    });

    it('should initialize with valid Personal Access Token', () => {
      expect(() => {
        auth.initialize({
          type: 'api',
          apiKey: '[REDACTED]'
        });
      }).not.toThrow();

      expect(auth.isAuthenticated()).toBe(true);
      expect(auth.needsTokenRefresh()).toBe(false);
    });

    it('should throw error when missing required OAuth parameters', () => {
      expect(() => {
        auth.initialize({
          type: 'oauth',
          clientId: 'test-client-id',
          // Missing clientSecret and redirectUri
        } as any);
      }).toThrow();
    });
  });

  describe('getAuthorizationUrl', () => {
    it('should return valid authorization URL with OAuth config', () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      const url = auth.getAuthorizationUrl();
      expect(url).toContain('https://linear.app/oauth/authorize');
      expect(url).toContain('client_id=test-client-id');
      expect(url).toContain('redirect_uri=http%3A%2F%2Flocalhost%3A3000%2Fcallback');
    });

    it('should throw error when called with API Key config', () => {
      auth.initialize({
        type: 'api',
        apiKey: '[REDACTED]'
      });

      expect(() => {
        auth.getAuthorizationUrl();
      }).toThrow();
    });

    it('should throw error when called before initialization', () => {
      expect(() => {
        auth.getAuthorizationUrl();
      }).toThrow();
    });
  });

  describe('handleCallback', () => {
    it('should handle valid authorization code with OAuth config', async () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Mock the token exchange
      mockFetch.mockResolvedValueOnce(new Response(
        JSON.stringify({
          access_token: '[REDACTED]',
          refresh_token: '[REDACTED]',
          expires_in: 3600
        }),
        { status: 200 }
      ));

      await expect(auth.handleCallback('valid-code')).resolves.not.toThrow();
      expect(auth.isAuthenticated()).toBe(true);
    });

    it('should throw error when called with API Key config', async () => {
      auth.initialize({
        type: 'api',
        apiKey: '[REDACTED]'
      });

      await expect(auth.handleCallback('valid-code')).rejects.toThrow();
    });

    it('should throw error for invalid authorization code', async () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Mock failed token exchange
      mockFetch.mockResolvedValueOnce(new Response(
        JSON.stringify({
          error: 'invalid_grant'
        }),
        { status: 400 }
      ));

      await expect(auth.handleCallback('invalid-code')).rejects.toThrow();
    });
  });

  describe('needsTokenRefresh', () => {
    it('should return true when OAuth token is expired', () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Set expired token
      auth.setTokenData({
        apiKey: '[REDACTED]',
        refreshToken: '[REDACTED]',
        expiresAt: Date.now() - 1000
      });

      expect(auth.needsTokenRefresh()).toBe(true);
    });

    it('should return false for valid OAuth token', () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Set valid token
      auth.setTokenData({
        apiKey: '[REDACTED]',
        refreshToken: '[REDACTED]',
        expiresAt: Date.now() + 3600000 // 1 hour from now
      });

      expect(auth.needsTokenRefresh()).toBe(false);
    });

    it('should return false for API Key', () => {
      auth.initialize({
        type: 'api',
        apiKey: '[REDACTED]'
      });

      expect(auth.needsTokenRefresh()).toBe(false);
    });
  });

  describe('refreshAPIKey', () => {
    it('should successfully refresh OAuth token', async () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Set initial token data
      auth.setTokenData({
        apiKey: '[REDACTED]',
        refreshToken: '[REDACTED]',
        expiresAt: Date.now() - 1000 // Expired
      });

      // Mock successful token refresh
      mockFetch.mockResolvedValueOnce(new Response(
        JSON.stringify({
          access_token: '[REDACTED]',
          refresh_token: '[REDACTED]',
          expires_in: 3600
        }),
        { status: 200 }
      ));

      await expect(auth.refreshAPIKey()).resolves.not.toThrow();
    });

    it('should throw error when refresh fails', async () => {
      auth.initialize({
        type: 'oauth',
        clientId: 'test-client-id',
        clientSecret: '[REDACTED]',
        redirectUri: 'http://localhost:3000/callback'
      });

      // Set initial token data
      auth.setTokenData({
        apiKey: '[REDACTED]',
        refreshToken: '[REDACTED]',
        expiresAt: Date.now() - 1000 // Expired
      });

      // Mock failed token refresh
      mockFetch.mockResolvedValueOnce(new Response(
        JSON.stringify({
          error: 'invalid_grant'
        }),
        { status: 400 }
      ));

      await expect(auth.refreshAPIKey()).rejects.toThrow();
    });

    it('should throw error when called with API Key config', async () => {
      auth.initialize({
        type: 'api',
        apiKey: '[REDACTED]'
      });

      await expect(auth.refreshAPIKey()).rejects.toThrow();
    });
  });
});

