import { LinearClient } from '@linear/sdk';
import { McpError, ErrorCode } from '@modelcontextprotocol/sdk/types.js';

/**
 * Solution Attempts:
 * 
 * 1. OAuth Flow with Browser (Initial Attempt)
 * - Used browser redirect and local server for OAuth flow
 * - Issues: Browser extensions interfering, CORS issues
 * - Status: Failed - Browser extensions and CORS blocking requests
 * 
 * 2. Personal Access Token (Current Attempt)
 * - Using API Key for initial integration tests
 * - Simpler approach without browser interaction
 * - Status: Working - Successfully authenticates and makes API calls
 * 
 * 3. Direct OAuth Token Exchange (Current Attempt)
 * - Using form-urlencoded content type as required by Linear
 * - Status: In Progress - Testing token exchange
 */

export interface OAuthConfig {
  type: 'oauth';
  clientId: string;
  clientSecret: string;
  redirectUri: string;
}

export interface APIKeyConfig {
  type: 'api';
  apiKey: string;
}

export type AuthConfig = OAuthConfig | APIKeyConfig;

export interface TokenData {
  apiKey: string;
  refreshToken: string;
  expiresAt: number;
}

export class LinearAuth {
  private static readonly OAUTH_AUTH_URL = 'https://linear.app/oauth';
  private static readonly OAUTH_TOKEN_URL = 'https://api.linear.app';
  private config?: AuthConfig;
  private tokenData?: TokenData;
  private linearClient?: LinearClient;

  constructor() {}

  public getAuthorizationUrl(): string {
    if (!this.config || this.config.type !== 'oauth') {
      throw new McpError(
        ErrorCode.InvalidRequest,
        'OAuth config not initialized'
      );
    }

    const params = new URLSearchParams({
      client_id: this.config.clientId,
      redirect_uri: this.config.redirectUri,
      response_type: 'code',
      scope: 'read,write,issues:create,offline_access',
      actor: 'application', // Enable OAuth Actor Authorization
      state: this.generateState(),
      access_type: 'offline',
    });

    return `${LinearAuth.OAUTH_AUTH_URL}/authorize?${params.toString()}`;
  }

  public async handleCallback(code: string): Promise<void> {
    if (!this.config || this.config.type !== 'oauth') {
      throw new McpError(
        ErrorCode.InvalidRequest,
        'OAuth config not initialized'
      );
    }

    try {
      const params = new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: this.config.clientId,
        client_secret: [REDACTED],
        redirect_uri: this.config.redirectUri,
        code,
        access_type: 'offline'
      });

      const response = await fetch(`${LinearAuth.OAUTH_TOKEN_URL}/oauth/token`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Accept': 'application/json'
        },
        body: params.toString()
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Token request failed: ${response.statusText}. Response: ${errorText}`);
      }

      const data = await response.json();
      this.tokenData = {
        apiKey: [REDACTED],
        refreshToken: [REDACTED],
        expiresAt: Date.now() + data.expires_in * 1000,
      };

      this.linearClient = new LinearClient({
        apiKey: [REDACTED],
      });
    } catch (error) {
      throw new McpError(
        ErrorCode.InternalError,
        `OAuth token exchange failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  public async refreshAPIKey(): Promise<void> {
    if (!this.config || this.config.type !== 'oauth' || !this.tokenData?.refreshToken) {
      throw new McpError(
        ErrorCode.InvalidRequest,
        'OAuth not initialized or no refresh token available'
      );
    }

    try {
      const params = new URLSearchParams({
        grant_type: 'refresh_token',
        client_id: this.config.clientId,
        client_secret: [REDACTED],
        refresh_token: [REDACTED]
      });

      const response = await fetch(`${LinearAuth.OAUTH_TOKEN_URL}/oauth/token`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Accept': 'application/json'
        },
        body: params.toString()
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Token refresh failed: ${response.statusText}. Response: ${errorText}`);
      }

      const data = await response.json();
      this.tokenData = {
        apiKey: [REDACTED],
        refreshToken: [REDACTED],
        expiresAt: Date.now() + data.expires_in * 1000,
      };

      this.linearClient = new LinearClient({
        apiKey: [REDACTED],
      });
    } catch (error) {
      throw new McpError(
        ErrorCode.InternalError,
        `Token refresh failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  public initialize(config: AuthConfig): void {
    if (config.type === 'api') {
      // Personal Access Token flow
      this.tokenData = {
        apiKey: [REDACTED],
        refreshToken: '', // Not needed for API Key
        expiresAt: Number.MAX_SAFE_INTEGER, // API Keys don't expire
      };
      this.linearClient = new LinearClient({
        apiKey: [REDACTED],
      });
    } else {
      // OAuth flow
      if (!config.clientId || !config.clientSecret || !config.redirectUri) {
        throw new McpError(
          ErrorCode.InvalidParams,
          'Missing required OAuth parameters: clientId, clientSecret, redirectUri'
        );
      }
      this.config = config;
    }
  }

  public getClient(): LinearClient {
    if (!this.linearClient) {
      throw new McpError(
        ErrorCode.InvalidRequest,
        'Linear client not initialized'
      );
    }
    return this.linearClient;
  }

  public isAuthenticated(): boolean {
    return !!this.linearClient && !!this.tokenData;
  }

  public needsTokenRefresh(): boolean {
    if (!this.tokenData || !this.config || this.config.type === 'api') return false;
    return Date.now() >= this.tokenData.expiresAt - 300000; // Refresh 5 minutes before expiry
  }

  // For testing purposes
  public setTokenData(tokenData: TokenData): void {
    this.tokenData = tokenData;
    this.linearClient = new LinearClient({
      apiKey: [REDACTED],
    });
  }

  private generateState(): string {
    return Math.random().toString(36).substring(2, 15);
  }
}

import { BaseHandler } from '../../../core/handlers/base.handler.js';
import { BaseToolResponse } from '../../../core/interfaces/tool-handler.interface.js';
import { LinearAuth } from '../../../auth.js';
import { LinearGraphQLClient } from '../../../graphql/client.js';

/**
 * Handler for authentication-related operations.
 * Manages both OAuth and API Key authentication flows.
 */
export class AuthHandler extends BaseHandler {
  constructor(auth: LinearAuth, graphqlClient?: LinearGraphQLClient) {
    super(auth, graphqlClient);
  }

  /**
   * Initializes OAuth flow with Linear.
   */
  async handleAuth(args: any): Promise<BaseToolResponse> {
    try {
      this.validateRequiredParams(args, ['clientId', 'clientSecret', 'redirectUri']);

      this.auth.initialize({
        type: 'oauth',
        clientId: args.clientId,
        clientSecret: [REDACTED],
        redirectUri: args.redirectUri,
      });

      const authUrl = this.auth.getAuthorizationUrl();

      return this.createResponse(
        `Please visit the following URL to authorize the application:\n${authUrl}`
      );
    } catch (error) {
      this.handleError(error, 'initialize authentication');
    }
  }

  /**
   * Handles OAuth callback after user authorization.
   */
  async handleAuthCallback(args: any): Promise<BaseToolResponse> {
    try {
      this.validateRequiredParams(args, ['code']);

      await this.auth.handleCallback(args.code);

      return this.createResponse('Successfully authenticated with Linear');
    } catch (error) {
      this.handleError(error, 'handle authentication callback');
    }
  }
}

import { LinearAuth } from '../src/auth.js';
import { config } from 'dotenv';
import express from 'express';
import open from 'open';

// Load environment variables
config();

async function main() {
  // Check if we're using API Key or OAuth
  if (process.env.LINEAR_API_KEY) {
    await testAPIKey();
  } else if (process.env.LINEAR_CLIENT_ID && process.env.LINEAR_CLIENT_SECRET && process.env.LINEAR_REDIRECT_URI) {
    await testOAuth();
  } else {
    console.error('ERROR: Either LINEAR_API_KEY or OAuth credentials (LINEAR_CLIENT_ID, LINEAR_CLIENT_SECRET, LINEAR_REDIRECT_URI) are required');
    process.exit(1);
  }
}

async function testAPIKey() {
  const auth = new LinearAuth();
  auth.initialize({
    type: 'api',
    apiKey: [REDACTED]
  });

  try {
    const client = auth.getClient();
    const viewer = await client.viewer;
    console.log('\nAPI Key Authentication successful!');
    console.log(`Connected as: ${viewer.name} (${viewer.email})`);
    console.log('\nTest Credentials:\n');
    console.log(`LINEAR_API_KEY=[REDACTED]}`);
  } catch (error) {
    console.error('Authentication failed:', error);
    process.exit(1);
  }
}

async function testOAuth() {
  const app = express();
  const port = 3000;
  const auth = new LinearAuth();

  auth.initialize({
    type: 'oauth',
    clientId: process.env.LINEAR_CLIENT_ID!,
    clientSecret: [REDACTED],
    redirectUri: process.env.LINEAR_REDIRECT_URI!
  });

  // Handle OAuth callback
  app.get('/callback', async (req, res) => {
    const { code, error } = req.query;

    if (error) {
      console.error('OAuth error:', error);
      res.send('Authentication failed. Check console for details.');
      return;
    }

    if (!code || typeof code !== 'string') {
      console.error('No authorization code received');
      res.send('No authorization code received');
      return;
    }

    try {
      // Exchange code for tokens
      await auth.handleCallback(code);

      // Get user info to verify authentication
      const client = auth.getClient();
      const viewer = await client.viewer;

      console.log('\nOAuth Authentication successful!');
      console.log(`Connected as: ${viewer.name} (${viewer.email})`);
      console.log('\nTest Credentials:\n');
      console.log(`LINEAR_AUTH_CODE=${code}`);
      console.log(`LINEAR_REDIRECT_URI=${process.env.LINEAR_REDIRECT_URI}`);

      // Get refresh token from auth instance
      const tokenData = (auth as any).tokenData;
      if (tokenData?.refreshToken) {
        console.log(`LINEAR_REFRESH_TOKEN=[REDACTED]}`);
      }

      res.send('Authentication successful! Check console for test credentials.');
    } catch (error) {
      console.error('Token exchange failed:', error);
      res.send('Token exchange failed. Check console for details.');
    }
  });

  // Start server and open auth URL
  const server = app.listen(port, () => {
    console.log(`\nStarting OAuth flow...\n`);

    // Get and open authorization URL
    const authUrl = auth.getAuthorizationUrl();
    console.log(`Opening: ${authUrl}\n`);
    open(authUrl);
  });

  // Handle server cleanup
  process.on('SIGINT', () => {
    server.close();
    process.exit();
  });
}

main().catch((error) => {
  console.error('Error:', error);
  process.exit(1);
});

